-- 14 days of month-to-date samples per project (drives the sparklines).
WITH RECURSIVE d(i) AS (SELECT 0 UNION ALL SELECT i + 1 FROM d WHERE i < 13) INSERT INTO samples (at, project, gross, net) SELECT strftime('%Y-%m-%dT12:00:00.000Z','now','-' || i || ' days'), 'acme-shop', 108.0150 * (14 - i + (abs(random()) % 60) / 100.0) / 14.6, 32.7198 * (14 - i) / 14 FROM d;
